import{a as b,b as f,c as e,d as E,h as r}from"./chunk-OG55QIAO.js";var t=[{key:"k",label:"T\xE9rmino k",align:"right",monoespaciado:!0},{key:"termino",label:"Aporte del t\xE9rmino",align:"right",monoespaciado:!0},{key:"suma",label:"Suma acumulada",align:"right",monoespaciado:!0},{key:"errorAbs",label:"Error absoluto",align:"right",monoespaciado:!0}];function C(a){return{k:String(a.k),termino:e(a.termino,10),suma:e(a.acumulado,10),errorAbs:e(a.errorAbsoluto,8)}}function i(a){return a.terminos.map(C)}var s=r(1,0,4),c=r(.5,0,3),L={id:"taylor-teoria-numerico",titulo:"Aproximar e\xB9 con cuatro t\xE9rminos de Taylor",tipo:"numerico",planteamiento:"Se desarrolla e^x alrededor de a = 0 y se corta en el t\xE9rmino de grado 4. Hay que estimar e\xB9 y comparar con la referencia num\xE9rica.",parametros:[{etiqueta:"x",valor:"1"},{etiqueta:"Centro a",valor:"0"},{etiqueta:"Grado n",valor:"4"}],interpretacion:"El polinomio suma 1 + x + x\xB2/2! + x\xB3/3! + x\u2074/4!. En x = 1 suma 2,708333; la referencia num\xE9rica de e es 2,718282. El resto es lo que queda afuera al cortar la serie.",pasos:["Escribir los t\xE9rminos hasta k = 4: 1, 1, 1/2, 1/6 y 1/24.","Sumar: 1 + 1 + 0,5 + 0,166667 + 0,041667 = 2,708333.","Restar la referencia: 2,718282 \u2212 2,708333 = 0,009948.","Acotar el resto: e^\u03BE \xB7 1\u2075/5!, con \u03BE entre 0 y 1; el m\xE1ximo es e/120 \u2248 0,02265.","Verificar que el error observado queda por debajo de la cota."],algoritmo:"Se eval\xFAan los t\xE9rminos (x\u2212a)^k/k! de forma acumulada y se suma hasta el grado pedido. La cota de Lagrange usa la derivada siguiente en el intervalo.",criterio:"El error real no se conoce sin evaluar e^x; la cota permite afirmar que el resto no supera e/120 sin depender de ese dato.",conclusion:`La aproximaci\xF3n es ${e(s.suma)} y la referencia num\xE9rica es ${e(s.real)}. El error absoluto es ${e(s.errorAbsoluto)} y la cota del resto es ${e(s.cotaResto)}.`,tabla:{columnas:t,filas:i(s)}},k={id:"taylor-teoria-casuistica",titulo:"Crecimiento continuo: aproximar e^0,5 con tres t\xE9rminos",tipo:"casuistica",enunciado:"Un modelo de crecimiento usa e^0,5 para proyectar un factor. Para una estimaci\xF3n r\xE1pida se corta la serie de Taylor en el t\xE9rmino de grado 3. \xBFCu\xE1nto se pierde?",planteamiento:"Aproximar e^0,5 con el desarrollo centrado en 0 hasta grado 3 y acotar el resto.",parametros:[{etiqueta:"x",valor:"0,5"},{etiqueta:"Centro a",valor:"0"},{etiqueta:"Grado n",valor:"3"}],extraccion:{busqueda:"El exponente que aparece en el factor de crecimiento y el grado de corte.",datos:[{simbolo:"x",valor:"0,5",queEs:"exponente del factor"},{simbolo:"a",valor:"0",queEs:"centro del desarrollo"},{simbolo:"n",valor:"3",queEs:"\xFAltimo grado incluido"}],formulacion:"e^0,5 \u2248 1 + 0,5 + 0,5\xB2/2! + 0,5\xB3/3!; el resto se acota con Lagrange."},interpretacion:"El t\xE9rmino de grado 3 ya es peque\xF1o (0,020833). La cota del resto es del orden de 0,0043, as\xED que la aproximaci\xF3n sirve para una estimaci\xF3n de pocas cifras.",pasos:["T\xE9rminos: 1; 0,5; 0,125; 0,020833.","Suma: 1,645833.","Referencia num\xE9rica: 1,648721.","Error observado: 0,002888.","Cota: e^0,5 \xB7 0,5\u2074/4! \u2248 0,004294."],algoritmo:"Se usa el mismo desarrollo; el centro y el grado se eligen seg\xFAn la precisi\xF3n que se necesita.",criterio:"La cota debe ser mayor o igual que el error observado. Ac\xE1 0,004294 > 0,002888, como exige el teorema.",conclusion:`La aproximaci\xF3n es ${e(c.suma)} frente a ${e(c.real)} de referencia. El error absoluto es ${e(c.errorAbsoluto)} y la cota del resto es ${e(c.cotaResto)}.`,tabla:{columnas:t,filas:i(c)}},T={concepto:"La serie de Taylor reemplaza una funci\xF3n suave por un polinomio construido con sus derivadas en un punto. Para e^x es especialmente simple: todas las derivadas valen e^x, y en el centro a = 0 valen 1. Cortar la serie en el grado n deja un resto R\u2099, que es el error de truncamiento: no viene de la m\xE1quina, viene de haber decidido no sumar infinitos t\xE9rminos.",fundamento:"Cerca del centro, los t\xE9rminos (x\u2212a)^k/k! se hacen cada vez m\xE1s chicos y la suma se acerca a la funci\xF3n. El teorema de Taylor demuestra que la diferencia se puede escribir como el t\xE9rmino siguiente evaluado en un punto \u03BE intermedio, no en el centro. Eso convierte \u201Cme qued\xE9 corto\u201D en una cuenta concreta: para e^x, el resto es e^\u03BE \xB7 (x\u2212a)^(n+1)/(n+1)!, y como e^\u03BE es creciente, se acota con el mayor de los extremos.",cuandoFalla:"El polinomio es una aproximaci\xF3n LOCAL. Si x est\xE1 lejos del centro, el t\xE9rmino (x\u2212a)^(n+1) crece r\xE1pido y hacen falta muchos t\xE9rminos. Con x negativo, los t\xE9rminos alternan de signo y pueden cancelarse entre s\xED: la suma puede perder cifras por cancelaci\xF3n aunque el resto te\xF3rico sea chico. El error de truncamiento tampoco incluye el error de redondeo de cada operaci\xF3n; para valores muy grandes de x, ambos compiten.",precision:"Para e^x en el intervalo entre a y x, |R\u2099| \u2264 e^max(a,x) \xB7 |x\u2212a|^(n+1)/(n+1)!. La cota es conservadora: puede ser bastante mayor que el error real. No es una promesa de que el resultado tenga exactamente esa cantidad de cifras, sino un techo que el resto no supera si la aritm\xE9tica fuera exacta.",recursos:[{titulo:"Serie de Taylor (Wikipedia, espa\xF1ol)",url:"https://es.wikipedia.org/wiki/Serie_de_Taylor",tipo:"lectura",descripcion:"La definici\xF3n, los ejemplos y la relaci\xF3n con la aproximaci\xF3n local."},{titulo:"Teorema de Taylor (Wikipedia, espa\xF1ol)",url:"https://es.wikipedia.org/wiki/Teorema_de_Taylor",tipo:"lectura",descripcion:"El resto de Lagrange y las formas de acotar el error de truncamiento."}],algoritmo:{formula:"e^x \u2248 \u03A3\u2096\u208C\u2080\u207F (x\u2212a)\u1D4F/k!;  |R\u2099| \u2264 e^max(a,x)\xB7|x\u2212a|\u207F\u207A\xB9/(n+1)!",criterios:[{nombre:"Centro del desarrollo",explicacion:"Mientras m\xE1s cerca est\xE9 x del centro, m\xE1s r\xE1pido baja el t\xE9rmino (x\u2212a)^(n+1)."},{nombre:"Grado del corte",explicacion:"Cada t\xE9rmino adicional agrega una potencia y un factorial; el error baja, pero no gratis."},{nombre:"Cota del resto",explicacion:"Es un techo te\xF3rico. Se calcula con el m\xE1ximo de la derivada siguiente en el intervalo, no con el valor en x."}],pasos:["Elegir el centro a y el grado n.","Calcular los t\xE9rminos (x\u2212a)^k/k! de forma acumulada.","Sumar hasta k = n.","Acotar el resto con la derivada (n+1) y el intervalo.","Comparar la cota con la precisi\xF3n que pide el problema."],ventajas:["Convierte una funci\xF3n complicada en sumas y productos.","Da una cota expl\xEDcita del error de truncamiento.","Muestra por qu\xE9 O(h\u207F) depende tanto de la distancia al centro."],limitaciones:["La cota puede ser muy conservadora.","Lejos del centro requiere muchos t\xE9rminos o un cambio de centro.","No controla el error de redondeo de las operaciones."],recomendaciones:["Desarrolla alrededor de un punto cercano al valor que vas a evaluar.","No confundas el error observado con la cota: la cota es un techo.","Para x negativo, revisa la cancelaci\xF3n adem\xE1s de la cota."]},ejemploNormal:L,ejemploCasuistica:k},x=r(2,0,5),g=r(-.5,0,3),y=r(.1,0,2),v=r(1.5,0,6),h=[{id:"taylor-ejemplo-1",titulo:"e\xB2 con cinco t\xE9rminos",tipo:"numerico",planteamiento:"Aproximar e\xB2 con el desarrollo centrado en 0 hasta grado 5.",parametros:[{etiqueta:"x",valor:"2"},{etiqueta:"Centro",valor:"0"},{etiqueta:"Grado",valor:"5"}],interpretacion:"Los t\xE9rminos crecen hasta k = 2 y despu\xE9s empiezan a bajar. La suma de seis t\xE9rminos se acerca a e\xB2, pero la cota del resto todav\xEDa es grande.",pasos:["T\xE9rminos: 1, 2, 2, 1,333333, 0,666667 y 0,266667.","Suma: 7,266667.","Referencia num\xE9rica: 7,389056.","Error: 0,122389.","Cota: e\xB2 \xB7 2\u2076/6! \u2248 0,6568."],algoritmo:"Suma acumulada de (2)^k/k! para k = 0..5.",criterio:"La cota 0,6568 es mayor que el error observado 0,1224.",conclusion:`La aproximaci\xF3n es ${e(x.suma)} y el error observado ${e(x.errorAbsoluto)}. La cota del resto es ${e(x.cotaResto)}.`,tabla:{columnas:t,filas:i(x)}},{id:"taylor-ejemplo-2",titulo:"e^(\u22120,5) con tres t\xE9rminos",tipo:"numerico",planteamiento:"Aproximar e^(\u22120,5) centrado en 0 hasta grado 3.",parametros:[{etiqueta:"x",valor:"\u22120,5"},{etiqueta:"Centro",valor:"0"},{etiqueta:"Grado",valor:"3"}],interpretacion:"Los t\xE9rminos alternan de signo. La suma queda en 0,604167, un poco por debajo de la referencia 0,606531.",pasos:["T\xE9rminos: 1; \u22120,5; 0,125; \u22120,020833.","Suma: 0,604167.","Referencia: 0,606531.","Error: 0,002364.","Cota: e\u2070 \xB7 0,5\u2074/4! = 0,002604."],algoritmo:"Se eval\xFAa (x\u2212a)^k/k! con x negativo; el signo alterna.",criterio:"La cota 0,002604 supera apenas al error 0,002364.",conclusion:`La aproximaci\xF3n es ${e(g.suma)}; el error absoluto es ${e(g.errorAbsoluto)} y la cota ${e(g.cotaResto)}.`,tabla:{columnas:t,filas:i(g)}},{id:"taylor-ejemplo-3",titulo:"e^0,1 con dos t\xE9rminos",tipo:"casuistica",enunciado:"Para estimar el inter\xE9s continuo de un periodo corto se usa e^0,1. Se quiere una aproximaci\xF3n de dos t\xE9rminos y saber si alcanza para tres cifras.",planteamiento:"Aproximar e^0,1 con el desarrollo centrado en 0 hasta grado 2.",parametros:[{etiqueta:"x",valor:"0,1"},{etiqueta:"Centro",valor:"0"},{etiqueta:"Grado",valor:"2"}],extraccion:{busqueda:"El exponente del factor y el grado de la aproximaci\xF3n.",datos:[{simbolo:"x",valor:"0,1",queEs:"exponente"},{simbolo:"n",valor:"2",queEs:"grado"}],formulacion:"e^0,1 \u2248 1 + 0,1 + 0,1\xB2/2."},interpretacion:"Con x cerca de 0, el t\xE9rmino cuadr\xE1tico ya es 0,005 y el c\xFAbico 0,000167. La aproximaci\xF3n de grado 2 deja un error del orden de 0,00017.",pasos:["T\xE9rminos: 1, 0,1 y 0,005.","Suma: 1,105.","Referencia: 1,105170.","Error: 0,000170.","Cota: e^0,1 \xB7 0,1\xB3/6 \u2248 0,000184."],algoritmo:"Se corta en grado 2; la cota usa la derivada tercera.",criterio:"El error es menor que 0,0002, suficiente para tres decimales en este caso.",conclusion:`La aproximaci\xF3n ${e(y.suma)} deja un error de ${e(y.errorAbsoluto)}. La cota es ${e(y.cotaResto)}.`,tabla:{columnas:t,filas:i(y)}},{id:"taylor-ejemplo-4",titulo:"e^1,5 con seis t\xE9rminos",tipo:"casuistica",enunciado:"Un modelo de crecimiento evaluado en x = 1,5 necesita una aproximaci\xF3n de Taylor de grado 6. Se quiere ver cu\xE1nto mejora al agregar t\xE9rminos.",planteamiento:"Aproximar e^1,5 centrado en 0 hasta grado 6.",parametros:[{etiqueta:"x",valor:"1,5"},{etiqueta:"Centro",valor:"0"},{etiqueta:"Grado",valor:"6"}],extraccion:{busqueda:"El valor de x y el grado m\xE1ximo del polinomio.",datos:[{simbolo:"x",valor:"1,5",queEs:"punto de evaluaci\xF3n"},{simbolo:"n",valor:"6",queEs:"grado del corte"}],formulacion:"e^1,5 \u2248 \u03A3\u2096\u208C\u2080\u2076 1,5\u1D4F/k!."},interpretacion:"Al estar m\xE1s lejos del centro que en los ejemplos anteriores, hacen falta m\xE1s t\xE9rminos. La cota de grado 6 ya es del orden de 0,006, aunque el error observado es menor.",pasos:["Calcular los siete t\xE9rminos y acumularlos.","Comparar con la referencia num\xE9rica e^1,5.","Calcular la cota con e^1,5 \xB7 1,5\u2077/7!.","Verificar que la cota sea mayor que el error observado."],algoritmo:"Misma suma acumulada, con x = 1,5 y n = 6.",criterio:"La cota es un techo; no se exige que el error observado la iguale.",conclusion:`La aproximaci\xF3n es ${e(v.suma)}; el error absoluto ${e(v.errorAbsoluto)}; la cota ${e(v.cotaResto)}.`,tabla:{columnas:t,filas:i(v)}}];function l(a,m,p,n,o){return{id:a,tipo:"opcion-multiple",enunciado:m,opciones:p,correcta:n,explicacion:o}}var q=r(.5,0,3),u=r(-1,0,4),d=r(2,0,4),j=[{id:"taylor-ejercicio-1",titulo:"Aproximar e^0,5 con grado 3",tipo:"numerico",planteamiento:"Suma los t\xE9rminos de Taylor de e^0,5 centrados en 0 hasta grado 3.",parametros:[{etiqueta:"x",valor:"0,5"},{etiqueta:"Centro",valor:"0"},{etiqueta:"Grado",valor:"3"}],interpretacion:"La suma incluye k = 0, 1, 2 y 3.",pasos:["1 + 0,5 + 0,125 + 0,020833.","Suma: 1,645833."],algoritmo:"\u03A3 0,5^k/k! para k = 0..3.",criterio:"La referencia num\xE9rica es 1,648721; el error es 0,002888.",conclusion:`La aproximaci\xF3n es ${e(q.suma)}.`,tabla:{columnas:t,filas:i(q)},pista:"El t\xE9rmino k = 3 es 0,5\xB3/3! = 0,125/6.",cuestionario:[l("taylor-e1-q1","\xBFCu\xE1ntos t\xE9rminos se suman si el grado es 3?",[{id:"a",texto:"Tres t\xE9rminos: k = 1, 2 y 3."},{id:"b",texto:"Cuatro t\xE9rminos: k = 0, 1, 2 y 3."},{id:"c",texto:"Solo el t\xE9rmino de grado 3."}],"b","La suma de Taylor empieza en k = 0, as\xED que un grado 3 incluye cuatro t\xE9rminos."),l("taylor-e1-q2","\xBFCu\xE1l es el t\xE9rmino de grado 3?",[{id:"a",texto:"0,125"},{id:"b",texto:"0,020833"},{id:"c",texto:"0,5"}],"b","0,5\xB3/3! = 0,125/6 \u2248 0,020833.")],resolucion:{valorCorrecto:q.suma,tolerancia:1e-6,etiqueta:"Aproximaci\xF3n de e^0,5",respuestaFinalTexto:e(q.suma)},formatoRespuesta:"escalar"},{id:"taylor-ejercicio-2",titulo:"e^(\u22121) con cuatro t\xE9rminos",tipo:"numerico",planteamiento:"Aproxima e^(\u22121) con el desarrollo centrado en 0 hasta grado 4.",parametros:[{etiqueta:"x",valor:"\u22121"},{etiqueta:"Centro",valor:"0"},{etiqueta:"Grado",valor:"4"}],interpretacion:"Los t\xE9rminos alternan: 1, \u22121, 0,5, \u22120,166667 y 0,041667.",pasos:["Sumar con signos alternados.","Resultado: 0,375."],algoritmo:"\u03A3 (\u22121)^k/k! para k = 0..4.",criterio:"La referencia es 0,367879; el error es 0,007121.",conclusion:`La aproximaci\xF3n es ${e(u.suma)} y el error ${e(u.errorAbsoluto)}.`,tabla:{columnas:t,filas:i(u)},pista:"No olvides el signo: (\u22121)^k alterna entre + y \u2212.",cuestionario:[l("taylor-e2-q1","\xBFPor qu\xE9 los t\xE9rminos cambian de signo?",[{id:"a",texto:"Porque x es negativo y las potencias alternan."},{id:"b",texto:"Porque el factorial es negativo."},{id:"c",texto:"Porque el centro no es cero."}],"a","Con x = \u22121, x^k vale \u22121 en los impares y +1 en los pares."),l("taylor-e2-q2","\xBFQu\xE9 t\xE9rmino de grado 4 se suma?",[{id:"a",texto:"\u22120,041667"},{id:"b",texto:"0,041667"},{id:"c",texto:"0,166667"}],"b","(\u22121)\u2074/4! = 1/24 \u2248 0,041667; el signo es positivo.")],resolucion:{valorCorrecto:u.suma,tolerancia:1e-6,etiqueta:"Aproximaci\xF3n de e^(\u22121)",respuestaFinalTexto:e(u.suma)},formatoRespuesta:"escalar"},{id:"taylor-ejercicio-3",titulo:"Una cota para e\xB2",tipo:"casuistica",enunciado:"Un equipo aproxima e\xB2 con Taylor de grado 4 centrado en 0. Antes de usar el resultado quiere saber qu\xE9 techo te\xF3rico tiene el resto.",planteamiento:"Calcular la cota de Lagrange del resto para x = 2, a = 0 y n = 4.",parametros:[{etiqueta:"x",valor:"2"},{etiqueta:"Centro",valor:"0"},{etiqueta:"Grado",valor:"4"}],extraccion:{busqueda:"El punto de evaluaci\xF3n, el centro y el grado del corte.",datos:[{simbolo:"x",valor:"2",queEs:"punto de evaluaci\xF3n"},{simbolo:"a",valor:"0",queEs:"centro"},{simbolo:"n",valor:"4",queEs:"grado"}],formulacion:"|R\u2084| \u2264 e^2 \xB7 2\u2075/5!."},interpretacion:"La cota usa el m\xE1ximo de e^\u03BE en [0,2], que es e\xB2, y la distancia 2 elevada a 5.",pasos:["e\xB2 \u2248 7,389056.","2\u2075 = 32.","5! = 120.","Cota: 7,389056 \xB7 32/120 \u2248 1,9704."],algoritmo:"Aplicar la f\xF3rmula del resto de Lagrange con la derivada quinta de e^x.",criterio:"La cota es 1,9704; el error real de la suma de grado 4 es 0,389056.",conclusion:`La cota del resto es ${e(d.cotaResto)}; el error observado es ${e(d.errorAbsoluto)}.`,tabla:{columnas:t,filas:i(d)},pista:"En la cota va el m\xE1ximo de e^\u03BE en el intervalo, no el valor en x = 0.",cuestionario:[l("taylor-e3-q1","\xBFQu\xE9 valor de e^\u03BE se usa para acotar?",[{id:"a",texto:"e\u2070 = 1, porque el centro es 0."},{id:"b",texto:"e\xB2, porque es el m\xE1ximo en [0, 2]."},{id:"c",texto:"e^0,5, porque \u03BE est\xE1 en el medio."}],"b","e^\u03BE es creciente; en [0,2] el m\xE1ximo est\xE1 en \u03BE = 2."),l("taylor-e3-q2","\xBFQu\xE9 potencia de 2 aparece en la cota?",[{id:"a",texto:"2\u2074"},{id:"b",texto:"2\u2075"},{id:"c",texto:"2\u2076"}],"b","El resto de grado 4 usa la derivada quinta, entonces la potencia es n+1 = 5.")],resolucion:{valorCorrecto:d.cotaResto,tolerancia:.001,etiqueta:"Cota del resto",respuestaFinalTexto:e(d.cotaResto)},formatoRespuesta:"escalar"}],S=[{key:"x",etiqueta:"Valor de x",ayuda:"El punto donde quieres evaluar e^x.",requisito:"N\xFAmero finito.",valorInicial:"1",tipo:"text",placeholder:"1"},{key:"centro",etiqueta:"Centro a",ayuda:"El punto alrededor del cual se desarrolla la serie. Para e^x se suele usar 0.",requisito:"N\xFAmero finito.",valorInicial:"0",tipo:"text",placeholder:"0"},{key:"grado",etiqueta:"Grado n",ayuda:"\xDAltimo grado incluido. La suma va desde k = 0 hasta k = n.",requisito:"Entero entre 0 y 12.",valorInicial:"4",tipo:"number",placeholder:"4"}];function $(a){let m=b(a.x??""),p=b(a.centro??""),n=f(a.grado??"");if(m===null||p===null)return{exito:!1,conclusion:"Escribe valores num\xE9ricos v\xE1lidos para x y el centro."};if(n===null||n<0||n>12)return{exito:!1,conclusion:"El grado debe ser un entero entre 0 y 12."};try{let o=r(m,p,n);return{exito:!0,resultado:e(o.suma,10),etiquetaResultado:"Aproximaci\xF3n de e^x",detalle:e(o.errorAbsoluto,10),etiquetaDetalle:"Error absoluto",conclusion:`La referencia num\xE9rica es e^x \u2248 ${e(o.real,10)}. La cota del resto es ${e(o.cotaResto)} y el error relativo ${E(o.errorRelativo)}.`,filas:i(o),columnas:t}}catch(o){return{exito:!1,conclusion:o instanceof Error?o.message:"No se pudo calcular la serie."}}}export{t as a,T as b,h as c,j as d,S as e,$ as f};
